1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const COMPONENT_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_PREMIUM = 60;
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const CURSE_SURCHARGE_PERCENT = 50;
30	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
31	const HIGH_ENCHANTMENT_THRESHOLD = 5;
32	
33	const percentOf = (amount: number, percent: number): number =>
34	  (amount * percent) / 100;
35	
36	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
37	
38	const componentGroupPremium = (count: number): number =>
39	  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;
40	
41	const firstInsuranceSurcharge = (base: number): number =>
42	  percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
43	
44	const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);
45	
46	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
47	
48	const isMainItem = (item: Item): boolean => !isComponent(item);
49	
50	const countByType = (items: Item[]): Map<string, number> => {
51	  const counts = new Map<string, number>();
52	  for (const item of items) {
53	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
54	  }
55	  return counts;
56	};
57	
58	const componentsTotalByType = (components: Item[]): number =>
59	  [...countByType(components).values()].reduce(
60	    (total, count) => total + componentGroupPremium(count),
61	    0,
62	  );
63	
64	const itemsBasePremium = (items: Item[]): number => {
65	  const components = items.filter(isComponent);
66	  const mainItems = items.filter(isMainItem);
67	  const mainItemsTotal = mainItems.reduce(
68	    (sum, item) => sum + basePremium(item),
69	    0,
70	  );
71	  return mainItemsTotal + componentsTotalByType(components);
72	};
73	
74	const itemSurcharge = (item: Item): number => {
75	  const base = basePremium(item);
76	  const curse = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
77	  const highEnchantment =
78	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
79	      ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
80	      : 0;
81	  return curse + highEnchantment;
82	};
83	
84	const itemSurcharges = (items: Item[]): number =>
85	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
86	
87	const LOYALTY_DISCOUNT_PERCENT = 20;
88	const LOYALTY_THRESHOLD_YEARS = 2;
89	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
90	
91	const loyaltyDiscount = (customer: Customer, base: number): number =>
92	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
93	    ? percentOf(base, LOYALTY_DISCOUNT_PERCENT)
94	    : 0;
95	
96	const followUpContractDiscount = (contractIndex: number, base: number): number =>
97	  contractIndex > 0 ? percentOf(base, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT) : 0;
98	
99	const policyModifiers = (
100	  customer: Customer,
101	  contractIndex: number,
102	  base: number,
103	): number =>
104	  firstInsuranceSurcharge(base) -
105	  loyaltyDiscount(customer, base) -
106	  followUpContractDiscount(contractIndex, base);
107	
108	export const quote = (
109	  customer: Customer,
110	  items: Item[],
111	  contractIndex: number,
112	): number => {
113	  const base = itemsBasePremium(items);
114	  const total =
115	    base +
116	    policyModifiers(customer, contractIndex, base) +
117	    itemSurcharges(items) +
118	    PROCESSING_FEE;
119	  return roundInMhpcoFavor(total);
120	};
121	
122	export interface Damage {
123	  itemType: string;
124	  amount: number;
125	}
126	
127	export interface Incident {
128	  cause: string;
129	  damages: Damage[];
130	}
131	
132	export interface ClaimResult {
133	  payout: number;
134	  remainingCap: number;
135	}
136	
137	const DEDUCTIBLE = 100;
138	const CAP_MULTIPLIER = 2;
139	
140	const INSURANCE_VALUES: Record<string, number> = {
141	  sword: 1000,
142	  amulet: 600,
143	  staff: 800,
144	  potion: 400,
145	  rune: 250,
146	  moonstone: 250,
147	};
148	
149	const insuranceValue = (item: Item): number => INSURANCE_VALUES[item.type] ?? 0;
150	
151	const insuranceSum = (items: Item[]): number =>
152	  items.reduce((sum, item) => sum + insuranceValue(item), 0);
153	
154	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
155	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
156	
157	const reimbursedAmount = (item: Item, amount: number): number =>
158	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
159	    ? percentOf(amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
160	    : amount;
161	
162	const damagePayout = (damage: Damage, item: Item): number =>
163	  Math.max(0, reimbursedAmount(item, damage.amount) - DEDUCTIBLE);
164	
165	const insuredItemFor = (items: Item[], damage: Damage): Item =>
166	  items.find((item) => item.type === damage.itemType) as Item;
167	
168	const validateDamageCounts = (items: Item[], damages: Damage[]): void => {
169	  const insuredCounts = countByType(items);
170	  const damageCounts = new Map<string, number>();
171	  for (const damage of damages) {
172	    const next = (damageCounts.get(damage.itemType) ?? 0) + 1;
173	    if (next > (insuredCounts.get(damage.itemType) ?? 0)) {
174	      throw new Error(
175	        `More ${damage.itemType} damages than insured items in the policy`,
176	      );
177	    }
178	    damageCounts.set(damage.itemType, next);
179	  }
180	};
181	
182	export const claim = (
183	  items: Item[],
184	  incident: Incident,
185	  priorPayouts: number,
186	): ClaimResult => {
187	  validateDamageCounts(items, incident.damages);
188	  const cap = insuranceSum(items) * CAP_MULTIPLIER;
189	  const remainingBefore = cap - priorPayouts;
190	  const rawPayout = incident.damages.reduce(
191	    (sum, damage) => sum + damagePayout(damage, insuredItemFor(items, damage)),
192	    0,
193	  );
194	  const payout = Math.min(rawPayout, remainingBefore);
195	  return { payout, remainingCap: remainingBefore - payout };
196	};
